contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        require(tos.length == vals.length);
        // observe before-values
        address before_from = c.from();
        address before_caddress = c.caddress();
        bool reverted;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // If call did not revert then it must have returned true, and public addresses unchanged
        assert(reverted || (ret == true && c.from() == before_from && c.caddress() == before_caddress));
    }
    receive() external payable {}
}

